SELECT MAX(sale_price) AS highest_price
FROM nlq.listings
WHERE category = 'textbooks' AND sale_price IS NOT NULL;

SELECT COUNT(*) AS comment_count
FROM nlq.reviews
WHERE comment IS NOT NULL;

select count(*) as conversations_no_reply
from nlq.conversations
where first_seller_reply_at is null;

SELECT COUNT(*) AS self_removed_listings
FROM nlq.listings_all
WHERE status = 'removed';

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (resolved_at - filed_at))/86400)::numeric, 2) AS avg_days_to_resolve
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_without_photos
FROM nlq.listings_all
WHERE photo_count = 0;

SELECT COUNT(*) AS requests_waiting
FROM nlq.deals d
WHERE d.status = 'requested';
